  "gl74d": "権利行使価格が有利（ITM）か、値段どおり（ATM）か、不利（OTM）か。",
  "gl75t": "本質的価値",
  "gl75d": "今すぐ満期を迎えたらいくらになるか。マイナスにはならない。",
  "gl76t": "時間的価値",
  "gl76d": "プレミアムのうち本質的価値でない部分。満期にはゼロになる。",
  "gl77t": "乗数（マルチプライヤー）",
  "gl77d": "1枚あたりの原資産の単位数（米国株オプションは100）。レバレッジではない。",
  "gl78t": "建玉（Open interest）",
  "gl78d": "その権利行使価格で未決済のまま残る枚数。当日の売買高ではなく累積の関心を測る。",
  "gl79t": "インプライド・ボラティリティ（IV）",
  "gl79d": "市場が今日プレミアムに織り込んで払っているボラティリティ。過去に起きた分ではない。",
  "gl80t": "IV Rank",
  "gl80d": "今日のIVが過去1年の自身のレンジのどこにあるか、0から100で示す。",
  "gl81t": "スキュー（Skew）",
  "gl81d": "権利行使価格ごとにIVが違うこと。通常はOTMプットが最も高い。",
  "gl82t": "ボラティリティ・サーフェス",
  "gl82d": "全ての権利行使価格と満期のIVを一枚の起伏として見たもの。",
  "gl83t": "ボラティリティ・クラッシュ",
  "gl83d": "予定イベント直後にIVが急落すること。方向が当たってもプレミアムは下がる。",
  "gl84t": "デルタ",
  "gl84d": "原資産が1ドル上がるとプレミアムがどれだけ動くか。ITMで終わる確率の目安にもなる。",
  "gl85t": "ガンマ",
  "gl85d": "1ドルの値動きごとにデルタがどれだけ変わるか。ポジションが動く速さを測る。",
  "gl86t": "セータ",
  "gl86d": "1日経つごとにポジションが失う額。売り手なら味方になる。",
  "gl87t": "ベガ",
  "gl87d": "インプライド・ボラティリティが1ポイント上がると価値がどれだけ変わるか。",
  "gl88t": "ロー",
  "gl88d": "金利が1ポイント上がると価値がどれだけ変わるか。ほぼ常に最も影響が小さい。",
  "gl89t": "ブラック・ショールズ",
  "gl89d": "IV・残存期間・金利からヨーロピアンオプションを値付けする標準モデル。",
  "gl90t": "プット・コール・パリティ",
  "gl90d": "コール・プット・原資産の間の固定的な関係。崩れれば裁定機会がある。",
  "gl91t": "割当（アサインメント）",
  "gl91d": "売ったオプションを行使されること。原資産を渡すか受け取ることになる。",
  "gl92t": "早期権利行使",
  "gl92d": "アメリカンオプションを満期前に行使すること。配当のあるコール以外はほぼ割に合わない。",
  "gl93t": "マックスペイン",
  "gl93d": "最も多くの枚数が無価値で満期を迎える権利行使価格。実際の建玉がないと読めない。",
  "gl94t": "ガンマ・エクスポージャー（GEX）",
  "gl94d": "ディーラーの累積ガンマ。プラスなら値動きを抑え、マイナスなら増幅する。",
  "gl95t": "ストップリミット",
  "gl95d": "価格に触れると指値注文を出す。価格は選べるが約定しないこともある。",
  "gl96t": "一部約定",
  "gl96d": "注文が一部しか成立せず、頼んだより小さいポジションで終わること。",
  "gl97t": "ポートフォリオ・リスク",
  "gl97d": "建玉すべてを同時に抱えた合計のリスク。1件ずつのリスクではない。",
  "gl98t": "ポジションサイズ",
  "gl98d": "ストップに掛かったとき、決めた額きっちりで済むように何枚建てるか。",
  "gl99t": "1トレードあたりのリスク",
  "gl99d": "1回の取引で失ってもよいと決めた口座の割合。",
  "gl100t": "Rマルチプル",
  "gl100d": "結果を初期リスクの倍数で測る方法。+2Rはリスクの2倍を稼いだということ。",
  "gl101t": "最大ドローダウン",
  "gl101d": "資産曲線の高値からその後の安値までの最も大きな下落。",
  "gl102t": "平均ペイオフ",
  "gl102d": "平均利益を平均損失で割った値。勝率と合わせて収支が成り立つかを決める。",
  "gl103t": "プロフィットファクター",
  "gl103d": "総利益を総損失で割った値。1を下回れば負けている手法。",
  "gl104t": "シャープレシオ",
  "gl104d": "ボラティリティ1単位あたりのリターン。好調な変動も同じく減点される。",
  "gl105t": "ソルティノレシオ",
  "gl105d": "シャープと同じ考え方だが、下落方向の変動だけを罰する。",
  "gl106t": "ケリー基準",
  "gl106d": "資産の成長を最大化する枚数の公式。実務ではその一部だけを使う。",
  "gl107t": "ATR",
  "gl107d": "一定期間に価格が動く平均的な値幅。余裕のあるストップを置くのに使う。",
  "gl108t": "相関",
  "gl108d": "2つの銘柄がどれだけ一緒に動くか。相関の高い2建玉はほぼ1つと同じ。",
  "gl109t": "ヒストリカル・ボラティリティ",
  "gl109d": "価格が実際に動いた分を過去データから測ったもの。IVはその予想版。",
  "gl1fill": "買値と売値の差は___と呼ばれます。",
  "gl2fill": "ボラティリティで注文が不利な価格で約定すると、___が生じます。",
  "gl7fill": "自己資金以上の規模で取引する___は、利益も損失も拡大させます。",
  "gl28fill": "価格の下側で下落が止まりやすい領域を___と呼びます。",
  "gl29fill": "価格の上側で上昇が止まりやすい領域を___と呼びます。",
  "gl30fill": "価格の支配的な方向（上昇か下降か）が___です。",
  "gl61fill": "大口がレンジ内でゆっくり買い、上昇に備えるとき、それは___です。",
  "gl62fill": "大口がレンジ内でゆっくり売り、下落に備えるとき、それは___です。",
  "gl63fill": "数日から数週間ポジションを保有するのは___トレードです。",
  "gl64fill": "数分の取引を数多く行い小さな利益を狙うのは___です。",
  "gl65fill": "切り上がる／切り下がる高値と安値の連なりが___を定義します。",
  "gl66fill": "大口の機関が出来高を入れ、価格が反応する領域は___です。",
  "gl67fill": "ローソク足間で価格が埋めやすい非効率な隙間は___です。",
  "gl68fill": "先に週足を分析し、次に分足へ下りるのが___の手法です。",
