  "srHowTitle": "見つけ方",
  "srHowBody": "サポートは価格が下落を止めて反発する水準で、需要が供給を上回ります。\nレジスタンスは価格が上昇を止めて反転する水準で、供給が需要を上回ります。\n水準に反発や拒絶が多く重なるほど信頼性が高まります。\n価格が勢いと出来高を伴って水準を抜けると、サポートとレジスタンスは役割を入れ替えます。",
