  "cyTitle": "暗号資産を深く",
  "cyIntro": "最も若く、最も変動が大きく、独自のルールを持つ市場:24時間365日、休みなく取引され、他の資産にはない公開のオンチェーンデータを持ち、株では見られない値動きを生む極端なレバレッジがある。ここでは、誇大宣伝の先にある本当の駆動要因を扱う。",
  "ixTitle": "指数とナスダック",
  "ixIntro": "指数を取引することは、個別企業リスクなしに一つの商品で経済全体に賭けることだ。だが指数は中立ではない:少数のメガキャップが方向を決め、時間外は先物が支配し、出来高が跳ねる特定の日がある。知っておくべきことはこれだ。",
  "fxTitle": "FXを深く",
  "fxIntro": "世界最大かつ最も流動的な市場(1日7兆ドル超)であり、最もマクロ的でもある:ここで取引するのは企業ではなく、対立する二つの経済だ。セッション、金利、ドルを理解すれば、値動きの90%が分かる。",
  "cmTitle": "コモディティ",
  "cmIntro": "株と違い、コモディティの背後には実物資産がある:バレル、地金、小麦のトン。これがルールを変える:企業の利益ではなく、目に見える需給・季節性・天候・地政学が支配する。",
  "atTitle": "アルゴリズム取引",
  "atIntro": "自分のルールをコード化し、機械が感情なく24時間・疲れ知らずで執行する。トレーダーの夢に聞こえるが、自動化はエッジも間違いも同じく増幅する。ここでは幻想ではなく、本当に何を伴うかを見る。",
  "cpTitle": "コピー&ソーシャルトレード",
  "cpIntro": "他のトレーダーの取引を自分の口座に自動で複製するプラットフォーム。作業を専門家に委ねるように聞こえるが、輝くリターンの裏のリスクを理解せずコピーするのは最も速く負ける方法の一つだ。ここでは批判的に見る方法を示す。",
  "liTitle": "長期投資",
  "liIntro": "誰もがトレーダーになりたいわけではない。多くの人にとって、退屈で一貫した資産形成はトレードに勝る。これがもう一つの道、エビデンスが支持する道だ:時間、複利、低コスト。",
  "txTitle": "トレードの税金",
  "txIntro": "税務当局が取る分は、あなたのリターンの非常に現実的な一部であり、ほとんど誰も計画しない。ここでは、取引がどう課税されるかを理解するための一般的な概念を示す。重要な注意:これは教育であり、税務アドバイスではない——規則は変わり、国と状況による。",
  "oiTitle": "オプション:インカムと権利行使割当",
  "oiIntro": "オプションのもう半分:投機ではなく、体系的にプレミアムを受け取り、権利行使を割り当てられたときに何が起きるかを理解すること。保守的なポートフォリオが使うインカム戦略。",
  "ovTitle": "オプション:ボラティリティ",
  "ovIntro": "オプションの価格は方向だけでは決まらず、何よりインプライド・ボラティリティに左右される。ここでは取引前にオプションが割高か割安かを見抜く方法を学ぶ——方向が当たっても負ける、その分かれ目だ。",
  "advancedOptionsTitle": "高度なオプション戦略",
  "advancedOptionsIntro": "リスク管理、収益創出、特定の市場環境からの利益獲得のための複雑なマルチレッグ戦略。",
