  "calendarSpreadTip": "ヒント:IVの変化は両レッグに等しく影響するが、時間的減衰は期近レッグでより速く効く。",
  "diagonalSpreadTitle": "ダイアゴナル・スプレッド",
  "diagonalSpreadDesc": "権利行使価格も満期も異なる。バーティカル・スプレッドの方向性バイアスと、カレンダー・スプレッドの時間的減衰の利点を組み合わせる。最も柔軟なマルチレッグ戦略。",
  "diagonalSpreadMaxProfit": "最大利益:変動——方向性と時間的減衰による",
  "diagonalSpreadMaxLoss": "最大損失:支払った正味デビット",
  "diagonalSpreadWhen": "最適な時:緩やかな方向性バイアスと、中程度のIV変化の予想",
  "diagonalSpreadTip": "ヒント:『貧者のカバードコール』とも呼ばれる(LEAPSを買い、期近コールを売る)。",
  "volatilityConceptsTitle": "ボラティリティの概念",
  "volatilityConceptsIntro": "インプライド・ボラティリティの理解はオプション取引に不可欠。IVはすべてのオプションの価格を決める。",
  "ivrTitle": "IVランク(IVR)",
  "ivrDesc": "現在のIVが52週レンジのどこにあるか。計算式:(現在IV − 52週安値)/(52週高値 − 52週安値)× 100。IVRが50超:プレミアムを売る。IVRが25未満:プレミアムを買う。",
  "ivrHigh": "IVR > 50:プレミアム売りの環境(アイアンコンドル、カバードコール)",
  "ivrLow": "IVR < 25:プレミアム買いの環境(デビット・スプレッド、ストラドル)",
  "ivPercentileTitle": "IVパーセンタイル",
  "ivPercentileDesc": "過去1年でIVが現在の水準を下回った日数の割合。80パーセンタイルは、IVが80%の期間より低かったことを意味し、歴史的に割高。IVRより頑健。",
  "volSkewTitle": "ボラティリティ・スキュー",
  "volSkewDesc": "OTMプットとOTMコールのIVの差。ネガティブ・スキュー(プット・スキュー):OTMプットのIVがコールより高い——下落ヘッジ需要。ポジティブ・スキュー:OTMコールがプットより割高。",
  "volSkewPut": "プット・スキュー:市場は恐怖、下落ヘッジ需要",
  "volSkewCall": "コール・スキュー:市場は強気、上昇投機の需要",
  "vixTitle": "VIX——恐怖指数",
  "vixDesc": "S&P500の30日期待ボラティリティを測る。市場と逆相関:相場が下がるとVIXは上がる。VIX > 30:強い恐怖、買いの好機の可能性。VIX < 15:楽観。",
  "vixHigh": "VIX > 30:強い恐怖——オプションは割高、プレミアムを売る",
  "vixLow": "VIX < 15:恐怖は小さい——オプションは割安、プレミアムを買う",
  "greeksDeepDiveTitle": "グリークスの詳細",
  "greeksDeepDiveIntro": "基礎を超えて——グリークスを使ってポートフォリオを動的に管理する方法。",
  "deltaHedgingTitle": "デルタ・ヘッジ",
  "deltaHedgingDesc": "正負のデルタを相殺してデルタ・ニュートラルのポートフォリオを保つ。100株の買い(デルタ +1.00)なら、ATMプットを2枚(各デルタ ~−0.50)買って中立化。デルタの変化に応じて常時リバランスが必要。",
  "deltaHedgingUse": "使う時:方向性リスクなしでシータまたはベガのエクスポージャーを切り離したいとき",
  "gammaRiskTitle": "ガンマ・リスク——加速装置",
  "gammaRiskDesc": "ガンマはデルタの変化の速さを測る。満期近くではATMオプションのガンマが急増——価格が動くたびにデルタが劇的に変わる。ショート・ガンマのポジションは最後の1〜2週間で非常に危険になる。",
  "gammaRiskWarning": "警告:ショート・ガンマ+想定外の動き=売りオプションで損失が無制限になりうる",
  "thetaDecayTitle": "シータ減衰カーブ",
  "thetaDecayDesc": "時間的減衰は線形ではない。オプションは最後の1か月で残存時間価値の約1/3を、最後の1週間でさらに1/3を失う。減衰カーブは満期近くで指数関数的に加速する。",
  "thetaDecayTarget": "目標:30〜45 DTEのオプションを売り、利益50%または21 DTEで手仕舞う",
  "vegaIVTitle": "ベガとインプライド・ボラティリティ",
  "vegaIVDesc": "ベガはIV変化に対する感応度を測る。買いオプションはIV拡大で利益(決算前に買う)。売りオプションはIV拡大で損をするが、収縮で利益(決算後に売る)。",
  "vegaLong": "ロング・ベガ:IV拡大の前に買う(決算、イベント)",
  "vegaShort": "ショート・ベガ:IVのピーク後、収縮が見込まれるときに売る(決算後に売る)",
