  "tweezersBottomName": "トゥイーザーボトム(毛抜き底)",
  "tweezersBottomDesc": "安値が同じ2本の連続したローソク足。その価格帯での強い支持と買い意欲のサイン。",
  "tweezersTopName": "トゥイーザートップ(毛抜き天井)",
  "tweezersTopDesc": "高値が同じ2本の連続したローソク足。その価格帯での強い抵抗と売り意欲のサイン。",
  "evTitle": "エビデンスに基づくトレード",
  "evIntro": "約束ではなくデータで『証明』されているものは何か?ここには、学術研究、規制当局、そしてファンド・銀行・トレーディングデスクの100年分のデータが示すものを集めた:実際にどれだけの人が負けるのか、どの戦略が数十年の統計に耐えたのか、プロはどうリスクを管理するのか。貫く糸は大数の法則:1回のトレードは運、1000回のトレードは統計だ。",
  "hzTitle": "時間帯と季節性",
  "hzIntro": "特定の時間帯や日付では、資金の流れ(始値・指標・引け・満期)によって相場は似た動きを『しやすい』。固定ルールでも買いシグナルでもなく、『いつ』取引し、いつ手を引くかを選ぶのに役立つ統計的な傾向だ。時刻はすべてフランクフルト時間/UTC+2(夏時間で±1時間ずれる)。",
  "msTitle": "マーケットストラクチャー",
  "msIntro": "どんなチャートパターンよりも前に、価格は高値と安値の連なりだ。『ストラクチャー』を読む——その高値・安値が切り上がるか、切り下がるか、横ばいか——ことで、トレンドと主導権が誰にあるかが分かる。チャートパターンもSMCもほぼすべてがこの土台に乗る。ここでは、その読み方と、いつ変わるかの見抜き方を学ぶ。",
  "mcTitle": "マクロ:景気循環・金利・ローテーション",
  "mcIntro": "マクロの地合いは、どんな単独チャートよりも市場全体を動かす。金利・インフレ・成長が、すべての船を持ち上げたり沈めたりする潮を決める。予測するのではなく、位置取りする:今が景気循環のどの局面かを知り、そこで何が効きやすいかを押さえる。",
  "cvTitle": "企業を深く評価する",
  "cvIntro": "ファンダメンタル分析は、企業が本当はいくらの価値かを探り、株式市場の価格と比べる。価格≠価値:優良企業でも高く買えば悪い投資になり、平凡な企業でも割安になりうる。ここでは、基本の4指標を超えて、数字を読み価値を見積もる方法を学ぶ。",
  "ofTitle": "オーダーフロー / テープリーディング",
  "ofIntro": "価格は結果、オーダーフローは原因。ここでは、完成したローソク足だけでなく、本当の買い圧・売り圧——誰が攻めているか、流動性はどこか、どこで吸収されるか——を読む方法を学ぶ。板情報(レベル2)と練習が要るが、プロのデイトレーダーが使うレンズだ。",
  "protoTitle": "トレード前のプロトコル",
  "protoIntro": "規律を具体的なルールに変える3つの道具:ブレーカー、エントリーのフィルター、そしてメンタルチェック。毎セッション・毎トレードの前に、この順で使う。",
  "brkTitle": "停止ルール(ブレーカー)",
  "brkIntro": "プラットフォームを閉じる前に、いくらまで負けてよいかを前もって決める。限度に達したら今日は終わり:例外なし、『あと1回』もなし。",
