  "tviTitle": "逆説:時間 vs 影響",
  "tviIntro": "時間の大半は分析に費やされるが、結果の大半は心理とリスク管理から生まれる。あなたは、実際に収益を左右するものとほぼ逆に時間を使っている。",
  "tviTimeLabel": "かける時間",
  "tviImpactLabel": "結果への影響",
  "tviTimeShort": "時間",
  "tviImpactShort": "影響",
  "tviCat1Name": "分析と戦略",
  "tviCat1Note": "チャート・指標・バックテスト・完璧なセットアップ探し",
  "tviCat2Name": "リスクと資金管理",
  "tviCat2Note": "ポジションサイズ・損切り・1トレードのリスク・総エクスポージャー",
  "tviCat3Name": "心理と規律",
  "tviCat3Note": "計画を守る・恐怖と欲を抑える・衝動で取引しない",
  "tviRoiLabel": "1時間あたりの効果",
  "tviTakeaway": "「トレードの成功は、戦略10%・資金管理30%・心理60%。」——ヴァン・K・タープの言葉とされる。メンタルとリスクに充てる1時間は、完璧な指標を探すもう1時間よりはるかに報われる。",
  "tviAction": "どうするか:分析はやめず、配分を見直す。最も報われるものに意図的に時間を割く:書いた計画、固定のリスク規則(1トレード1%)、感情的な失敗を振り返る日誌、そして熱くなったときに自分を止めるルーティン。",
  "tviDisclaimer": "影響の割合はヴァン・K・タープの古典的な配分(60/30/10)に従う。他の著者(ダグラス、スティーンバーガー)も近い数字(心理60〜80%)を挙げる。時間の割合は典型的な配分の目安であり、研究データではない。",
