  "gkIntro": "グリークスは、原資産・時間・ボラティリティ・金利という各変数が動いたときにオプション価格がどう変わるかを測る指標です。オプショントレーダーの計器盤であり、これ無しでは盲目飛行です。各カードに数値例を付けています。学んだら「オプション」セクションのブラック・ショールズ計算機で実践を。",
  "mlqTitle": "デリバティブの証拠金と強制ロスカット",
  "mlqIntro": "レバレッジをかけて先物や無期限契約を取引するなら、証拠金は命綱です。多くの口座は分析ミスではなく、取引所がいつ・どのように強制決済（清算）するかを理解していないことで消えていきます。このモジュールでは証拠金モード、ポジションモード、清算価格、そして操作的なヒゲからの防衛法を解説します。",
  "ntTitle": "ニュース・イベント取引",
  "ntIntro": "高インパクト指標（雇用統計、CPI、金利）は数秒で相場を動かす。前・最中・後に何をすべきかを知ることが、機会と口座破綻を分ける。ダッシュボードの経済カレンダーで時刻を把握しよう。",
  "smTitle": "市場センチメント",
  "smIntro": "群衆の感情——恐怖か強欲——を測る。極端ではセンチメントは逆張りの燃料になる。『全員』が強気なら、もう買い手は残っていない。この柱のCOT（実際の建玉）を補完する。",
  "imTitle": "インターマーケット分析",
  "imIntro": "どの市場も単独では動かない（ジョン・マーフィー）。ドル・債券・商品・株式は結ばれており、その関係を読むことがトレードを裏付ける（または否定する）マクロの文脈になる。CMT試験の15%を占めるのには理由がある。",
  "bcTitle": "市場の幅・サイクル・季節性",
  "bcIntro": "指数は5つの巨大株に支えられて上がり、残りは沈んでいることがある：幅は動きの『内部の健康』を測る。サイクルと季節性が統計的な『いつ』を加える。個人がほぼ見ないCMT試験の内容。",
  "bkrTitle": "ブローカー・規制・詐欺",
  "bkrIntro": "チャートで全て正しくやっても、預け先を間違えれば全てを失う。このモジュールでは10分でブローカーを検証する方法と、この業界に蔓延る詐欺の見抜き方を学ぶ。",
