  "thetaPositive_91e0f1": "プラスセータ:プレミアムを受け取ります。時間があなたに有利 — 価格が動かなければ、毎日タイムディケイで利益。",
  "thetaNeutral_91e0f2": "ニュートラルセータ:ロングとショートが相殺。時間よりも価格変動が重要。",
  "unlimitedRiskUp_91e0f3": "上昇方向に無制限リスク。高い証拠金と規律あるストップロスが必要。",
  "unlimitedRiskDown_91e0f4": "下落方向に無制限リスク。高い証拠金と規律あるストップロスが必要。",
  "maxLossDefined_91e0f5": "最大損失は${amount}で確定。何があってもそれ以上は損失しません。",
  "assignPut_91e0f6": "{symbol}が${strike}を下回り保有し続けると、ストライク価格で1契約あたり100株が割り当てられます。",
  "assignCall_91e0f7": "{symbol}が${strike}を上回り保有し続けると、1契約あたり100株を引き渡す(カバードコールの場合)か、損失で決済(ネイキッドの場合)する必要があります。",
  "ivHighLong_91e0f8": "高IV({iv}%):高額なプレミアムを支払います。決算後のIVクラッシュにより、方向が正しくても損失が出る可能性があります。",
  "ivHighShort_91e0f9": "高IV({iv}%):高額なプレミアムを受け取ります。ボラティリティ売り手に有利な状況。",
  "tipo_ua001": "タイプ",
