  "lotBinding": "制限要因",
  "lotOfAccount": "（口座比）",
  "lotUnknownSymbol": "{symbol} はカタログにないため、ロットサイズもpipもわかりません。別の銘柄を選ぶか、契約サイズを手入力できる計算デスクで算出してください。",
  "lotCrossPair": "このペアは {quote} 建てで、口座はドル建てです。換算にはここにない第三の為替レートが必要で、通貨を取り違えたロット数を出すくらいなら出さないほうがましです。",
  "lotFormula": "ロット =（決済通貨建てのリスク）/（pips × pip × 1ロットの単位数）· pipは定数ではなくカタログから",
  "patternBlocked_incomplete": "データが足りません。エントリー・ストップ・目標のすべてが必要で、ストップをエントリー価格に置くことはできません。",
  "patternBlocked_too_small": "そのリスクとストップ幅では最小のポジションすら成立しません。ストップが遠すぎるか、リスクが小さすぎます。",
  "patternCapped_margin": "サイズを縛っているのはリスクではなく証拠金です。そのストップが許すポジションを口座が支えられません。",
  "patternCapped_exposure": "サイズを縛っているのはリスクではなくエクスポージャーです。そのポジションは口座の10倍という上限を超えます。",
  "positionSizeCalcTitle_p002": "ポジションサイズ計算機",
  "monteCarloLockedTitle_p003": "モンテカルロシミュレーター",
