  "directionBearish_p008": "弱気",
  "percLongDesc_p009": "LONGでは価格が上昇すると利益になります。価格は{pct}%{dir}したため、{result}。",
  "percShortDesc_p010": "SHORTでは価格が下落すると利益になります。価格は{pct}%{dir}したため、{result}。",
