  "testimonialsTitle_l001": "トレーダーの声",
  "testimonialsSubtitle_l002": "数百人のプロトレーダーと個人投資家が、Trading Calculator PROで戦略を最適化しています。",
  "faqTitle_l003": "よくある質問",
  "faqSubtitle_l004": "始める前の一般的な疑問にお答えします。",
  "testimonial1Quote_l010": "闇雲なトレードから、R/R、position size、win rateの明確な指標を持つトレードへ。もう口座が大きなdrawdownに苦しむことはありません。",
  "testimonial1Author_l011": "Carlos M.",
  "testimonial1Role_l012": "仮想通貨デイトレーダー · 4年",
  "testimonial2Quote_l020": "Strategy OptimizerとAI Coachのおかげで、何時間もの分析時間を節約できています。計画的な取引1回で、毎月のコストを回収できています。",
  "testimonial2Author_l021": "Ana R.",
  "testimonial2Role_l022": "オプションスイングトレーダー",
  "testimonial3Quote_l030": "8ヶ月間毎日使っています。Monte Carloとジャーナル機能がリスクに対する考え方を変えました。星5つです。",
  "testimonial3Author_l031": "David L.",
  "testimonial3Role_l032": "独立トレーダー · Forex",
  "faqQ1_l040": "使用するには専門知識が必要ですか?",
  "faqA1_l041": "いいえ。アプリは各計算機をステップバイステップでガイドし、Education CenterではStop Lossの基本からオプションを使った高度な戦略まで網羅しています。リスクなしで試せる無料のDemo Traderもあります。",
  "faqQ2_l050": "いつでもサブスクリプションをキャンセルできますか?",
  "faqA2_l051": "はい。プロフィールから1クリックでキャンセルできます。縛りはありません。Lifetimeを購入した場合、アクセスは永続的で、継続的な支払いはありません。",
  "faqQ3_l060": "どの資産に対応していますか?",
  "faqA3_l061": "仮想通貨、Forex、米国株式(NYSE/NASDAQ)、指数(SPX、NDX、DAX等)、商品、先物に対応。暗号資産はリアルタイム。その他の市場は遅延する場合がありますデータを提供。",
  "faqQ4_l070": "Trade CoachのAIは別料金ですか?",
  "faqA4_l071": "いいえ。AI Trade Coach(Claude Sonnet 4.5)は全てのPremiumプランに含まれています。シニアメンターのように戦略を分析し、リスクを特定し、改善を提案します。",
  "faqQ5_l080": "モバイルで動作しますか?",
  "faqA5_l081": "はい。完全レスポンシブデザインです。計算機とダッシュボードはiOS/Androidで完璧に動作します。ネイティブアプリはQ2のロードマップに含まれています。",
  "tradingViewPreviewLabel_l090": "ダッシュボードプレビュー",
  "tradingViewLiveBadge_l091": "ライブデータ",
  "languageAutoDetected_l100": "言語が自動検出されました: {lang}。ヘッダーから変更できます。",
