  "shortExplanation_lev007": "{lev}xのSHORTの場合:価格が{pct}%{dir}すると、{res}は{roi}%になります(変動の{lev}倍の逆)。",
  "save_lev008": "保存",
  "calcPosition_pos001": "ポジション計算",
  "slDistanceLabel_pos002": "SL距離",
  "highLeverageWarning_pos003": "⚠ 高レバレッジ - ロスカットリスクが高い",
  "positionSizeExplanation_pos004": "{risk}%のリスクで、${sl}のSLが発動した場合、正確に${amount}を失います(口座の{pct}%)。",
  "feesAndDividends_adv001": "手数料と配当",
