  "ichiTitle": "一目均衡表（Ichimoku Kinko Hyo）",
  "smcTitle": "Smart Money / ICT",
  "optTitle": "オプション戦略",
  "optIntro": "コールとプットを組み合わせると、リスクを限定したポジションを作り、方向だけでなくボラティリティや時間の経過からも利益を得られる。各戦略のグリークスとペイオフ図はオプション計算機で確認しよう。",
  "smcIntro": "『スマートマネー』のアプローチ（ICTが広めた）は、機関投資家の足跡を追おうとする：どこで注文を積み上げ、どのように個人の流動性を狩り、価格がどこへ戻るか。裁量的な手法なので、魔法のシステムではなく『合流（コンフルエンス）』として使うこと。",
  "ichiIntro": "細田悟一が考案した日本発の『一目で均衡がわかる』チャート。5本の線と先行して描かれる『雲』が、トレンド・支持/抵抗・モメンタム・エントリーシグナルを一度に示します。相場を一目で読めるよう設計され、FXや暗号資産で非常に人気です。",
  "ewTitle": "エリオット波動理論",
  "ewIntro": "ラルフ・エリオットは、群集心理が繰り返す波動パターンで相場を動かすことを見いだしました。価格はトレンド方向に5波の『推進』で進み、その後3波で逆行修正します。この5-3の形は、数分から数十年まであらゆる次元で繰り返されます。",
