  "wyckoffTab": "Wyckoff Method",
  "wyckoffTitle": "Wyckoff Method",
  "wyckoffIntro": "ワイコフ理論は、20世紀初頭にリチャード・ワイコフが築いたテクニカル分析の枠組みです。価格・出来高・時間を観察し、大口の機関投資家（コンポジット・オペレーター）による仕込みと振るい落としの周期を見抜き、それと同じ方向で取引することを目指します。",
