  "cmtPosSizeTitle": "Position Size Calculator",
  "cmtPosSizeIntro": "固定のリスク率を、エントリーと損切りから正確な数量に変換します。リスク管理でもっとも重要な数字がこれです。切りのよいロット数からではなく、必ず損切りから逆算してください。",
