  "cmtKellyTitle": "ケリー基準の計算機",
  "cmtKellyIntro": "ケリー比率は、あなたの優位性のもとで数学的に最適な資金リスク率です。フルケリーは長期的な成長を最大化しますが変動が極端に激しく、プロはその一部だけを使います。",
  "cmtWinRate": "Win Rate (%)",
  "cmtAvgWin": "Avg Win (R or $)",
  "cmtAvgLoss": "Avg Loss (R or $)",
  "cmtFullKelly": "Full Kelly",
  "cmtFullKellySub": "max growth, max risk",
  "cmtHalfKelly": "Half Kelly",
  "cmtHalfKellySub": "common balance",
  "cmtQuarterKelly": "Quarter Kelly",
  "cmtQuarterKellySub": "保守的、推奨",
  "cmtPayoff": "Payoff ratio",
  "cmtExpectancy": "Expectancy",
  "cmtNoEdge": "この入力ではシステムに正の優位性がありません。ケリーが負ということは、勝率かペイオフが改善するまで何も賭けるべきではないという意味です。",
  "cmtKellyTip": "フルケリーで賭けると、通常50%を超えるドローダウンが出ます。多くのプロは1/2または1/4ケリーを用い、変動をはるかに抑えながら成長の大部分を取りにいきます。",
  "slGuideTitle": "損切り：固定か可変か",
  "slGuideIntro": "損切りをどこに置くかが、リスクも、R倍数も、最終的には期待値も決めます。相場の構造に沿って置いた損切りは現実に順応し、恣意的な固定幅の損切りは現実と戦います。",
  "slTypesTitle": "損切りの置き方は三通り",
  "slStructureName": "Structure-based",
  "slStructureDesc": "損切りは、あなたの根拠を否定する高安値・支持・抵抗のすぐ外側に置きます。どこで間違いなのかは相場が教えてくれます。順応的で理にかなった方法です。",
  "slAtrName": "Volatility-based (ATR)",
  "slAtrDesc": "損切り幅 = ATRの倍数（例：1.5×ATR）。荒れた局面では広がり、穏やかな局面では狭まるので、通常のノイズで振り落とされません。",
  "slFixedName": "Fixed (pips / %)",
  "slFixedDesc": "構造やボラティリティに関係なく、常に同じ幅（例：20pipsや2%）。単純ですが、その取引が実際に否定される位置を無視するため、サンプルが増えるほど静かに期待値を削っていきます。",
  "slBreakevenTitle": "最低リスクリワード比に「共通の正解」はありません",
  "slBreakevenIntro": "損益分岐のリスクリワード比は、あなたの勝率で完全に決まります。高勝率のシステムは1:1未満でも利益が出ますし、低勝率のトレンドシステムには大きなRが要ります。「常に1:2」は思い込みです。",
  "slColWinRate": "Win Rate",
  "slColBreakeven": "Break-even R:R",
  "slColProfitable": "Profitable above",
  "slBreakevenFormula": "損益分岐R =（1 − 勝率）÷ 勝率",
  "slKeyInsight": "恣意的な固定幅の損切りは固定のRを強います。それが実際の勝率と噛み合わなければ、「良い」セットアップですら期待値がマイナスになりえます。根拠が否定される位置に損切りを置き、リスクを一定に保つために数量を減らし、リスクリワード比は構造から導かせてください。",
  "otGuideTitle": "板（オーダーブック）と注文の種類",
  "otGuideIntro": "すべての取引は板の上で付け合わされます。板とは、待機している買い注文と売り注文が並ぶ生きたはしごです。これを理解すればスプレッド、流動性、スリッページが説明でき、機関投資家が使う隠し注文も見えてきます。",
  "otOrderBookTitle": "Limit Order Book",
  "otSpread": "SPREAD",
  "otAsksLabel": "Asks (offers)",
  "otAsksDesc": "価格より上で待機する売り指値。最も低い売り気配が、いま買うのに最良の価格です。",
  "otBidsLabel": "Bids",
  "otBidsDesc": "価格より下で待機する買い指値。最も高い買い気配が、いま売るのに最良の価格です。",
  "otDepthLabel": "Depth / liquidity",
  "otDepthDesc": "バーの長さ = 各価格帯で待機している数量。板が薄いと、成行注文はいくつもの価格帯を滑って約定します。",
  "otIcebergHint": "破線のバーはアイスバーグです。見えているのは先端だけで、約定するたびに残りが補充されます。",
  "otAdvancedTitle": "機関投資家向け・上級の注文タイプ",
  "otIcebergName": "Iceberg Order",
  "otIcebergDesc": "板には一度に小さな「先端」しか表示しない大口注文です。見えている一片が約定するたび、次が自動的に現れます。本当の数量を隠すことで、相場が大口に不利な方向へ走らないようにします。",
  "otHiddenName": "Hidden / Reserve Order",
  "otHiddenDesc": "公開板からは完全に見えません。意図をいっさい明かさずに流動性を供給します。完全な隠密性と引き換えに、同値の見える注文より後に約定するのが普通です（待ち行列の優先度が低い）。",
  "otOcoName": "OCO (One-Cancels-Other)",
  "otOcoDesc": "連動する2つの注文で、通常は利確と損切りです。一方が約定すると、もう一方は自動的に取り消されます。ポジションを上下で挟む標準的なやり方です。",
  "otFokIocName": "FOK / IOC",
  "otFokIocDesc": "フィル・オア・キルは全数量を即座に約定させるか、まるごと取り消します。イミディエイト・オア・キャンセルは今約定できる分だけ約定させ、残りを取り消します。どちらも、手の内を明かす待機注文を残さずに済みます。",
  "dowDiagramTitle": "相場サイクルと3つの局面",
  "dowDiagramIntro": "ダウ理論では、主要な上昇相場は3つの心理的局面をたどるとされます。価格は一直線ではなく、主要トレンドと二次的な反動が織りなす階段状で進みます。",
  "dowPhaseAccumulation": "Accumulation",
