  "dowDegreesTitle": "The three trend degrees",
  "dowDegreePrimaryName": "Primary trend",
  "dowDegreePrimaryDesc": "本流の潮 — 数か月から数年続きます。あなたが順張りしたい方向がこれです。両方の平均株価で転換が確認されて初めて終わります。",
  "dowDegreeSecondaryName": "Secondary reaction",
  "dowDegreeSecondaryDesc": "潮に逆らう波 — 数週間続く押し・戻りで、直前の値動きの1/3〜2/3を戻します。トレンドフォロワーが入り口を探すのはここです。",
  "dowDegreeMinorName": "Minor trend",
