  "dowVolumeConfirm": "出来高はトレンドを裏づけなければなりません。主要トレンドの方向で増え、二次的な反動では細るのが本来です。出来高を伴わないブレイクは疑ってかかるべきです。",
  "cmpIntro": "正しいスタイルとは、理論上の利回りが最も高いものではなく、あなたの使える時間と気質に合うものです。以下で現実的な得失を比べてください。",
