  "strat_csp_desc": "ストライク全額を現金で確保してプットを売却。ペイオフはショート・プットと同じだが必要資金が異なる。",
  "strat_protective_put_desc": "株式に下方のプット買いを加えた、免責付きの保険。",
  "strat_covered_put_desc": "株式の空売りにプット売りを組み合わせ、価格が上がらない限りプレミアムを得る。",
  "strat_covered_strangle_desc": "株式にアウト・オブ・ザ・マネーのコールとプットの売りを加える。プレミアムは二重、義務も両側。",
  "strat_ratio_call_write_desc": "株式に対しコールを2枚売り、1枚はカバード、1枚は裸。",
  "strat_ratio_put_write_desc": "株式の空売りに対しプットを2枚売り、1枚はカバード、1枚は裸。",
  "strat_stock_repair_desc": "含み損の株式に対し、コールを1枚買い上値で2枚売って、資金を足さずに損益分岐点を下げる。",
  "strat_call_calendar_desc": "期近コールを売り、同じコールを期先で買う。ショート脚の時間価値の減りが速いことで稼ぐ。",
  "strat_put_calendar_desc": "期近プットを売り、同じプットを期先で買う。",
  "strat_call_diagonal_desc": "ストライクの異なるカレンダー。上のショート脚が時間価値の収集に強気の傾きを加える。",
  "strat_put_diagonal_desc": "ストライクの異なるプット・カレンダー。下のショート脚が弱気の傾きを加える。",
  "strat_double_calendar_desc": "下にプット、上にコールの2つのカレンダー。価格がその間で終われば利益。",
