  "strat_jelly_roll_desc": "同一ストライクで満期の異なる2つの合成ポジションの差。価格は純粋に金利と配当。",
  "strat_pmcc_desc": "期先のディープITMコールを株式代わりにし、それに対して期近コールを売る。100株を買わないカバード・コール。",
