  "strat_xmas_put_desc": "1-3-2バタフライのプット版で、下方にずらしたもの。",
  "strat_bull_call_ladder_desc": "ブル・コール・スプレッドに上値でコールをもう1枚売る。追加クレジットと引き換えに上方向が無限リスクになる。",
  "strat_bear_call_ladder_desc": "下でコールを売り上で2枚買う。レンジでは損失、大幅上昇で利益。",
