  "optExitNote": "満期時の価格、往復手数料控除後。満期前に閉じると時間価値を残すことになります。",
  "calcDescPosition": "ストップに掛かったとき、リスクを取ると決めた口座の割合ちょうどで損失が止まるように数量を求めます。エントリーの「前」に行う計算です。",
  "calcDescLotsize": "ポジションサイズと同じ計算をFXのロット単位で行います。通貨ペアごとのpip価値と口座通貨を考慮します。",
  "calcDescPartialExit": "一括ではなく分割で決済したときの、平均決済価格と実際の損益。",
  "calcDescLeverage": "どの価格で強制決済されるか、レバレッジごとに必要証拠金がいくらかを示します。建てる「前」に強制決済までの距離を確認するためのものです。",
  "calcDescFutures": "先物1枚に必要な証拠金、ティック価値、損益を、市場ごとの乗数で計算します。",
  "calcDescTarget": "狙った利益率を達成するために必要な売却価格を、手数料込みで求めます。",
  "calcDescPercentage": "下落を取り戻すには何%上昇が必要かを示します。この非対称性は意外です — 50%の下落は、元に戻すだけで100%の上昇を要します。",
  "calcDescSpot": "現物で売買したとき、手数料を差し引いて実際に受け取る金額。",
  "calcDescMeasure": "チャートパターンが自身の高さから投影する価格目標。三角保ち合いやヘッドアンドショルダー、レンジはこうして測ります。",
  "calcDescFibonacci": "チャート上の2点間のフィボナッチ・リトレースメントとエクステンション。エントリーと目標の設定に使います。",
  "calcDescPattern": "特定のチャートパターンのエントリー・ストップ・目標を、リスクリワード比まで含めて算出します。",
  "calcDescMontecarlo": "同じ取引を順序だけ変えて数千回繰り返したとき、成績がどう散らばるかを示します。あなたの統計が許容する連敗の深さが見えます。",
  "calcDescSimulator": "自分のリスクルールを当てはめて、口座がフェーズごとにどう推移するか、いつロットを上げ下げすべきかを見ます。",
  "calcDescCompound": "利益を再投資したときに資金がどう増えるか。定期的な積み立てがあれば含めて計算します。",
  "helpAria": "説明を表示",
  "helpRiskPerTrade": "「この1回」の取引で失ってよい口座の割合です。合計ではありません。一般的には1〜2%：2%なら口座が半減するまで約35連敗を要しますが、10%ならわずか7連敗で済みます。",
  "helpStopDistance": "数量を決めるのはエントリーとストップの距離であり、その逆ではありません。ストップを近づけると同じリスクでより多く買えますが、掛かる回数も増えます。",
  "helpRequiredLeverage": "その建玉を自己資金で持つのに必要なレバレッジです。推奨値ではありません。値が大きいときは、口座に対してストップが遠すぎることを示しているのが普通です。",
  "helpAccountBalance": "今日の実際の残高を入れてください。期待値ではありません。リスク計算のすべてがこの数字に乗るため、切り上げると全ポジションが一律に大きくなります。",
  "helpPipValue": "通貨ペアが1pip動いたときの損益額です。ペアと口座通貨で変わります。EURUSDの1pipとUSDJPYの1pipは同じ価値ではありません。",
  "helpLotSize": "1標準ロットは基軸通貨10万通貨、ミニは1万、マイクロは1千です。0.35ロットという結果は35,000通貨であって35ではありません。",
  "helpLeverage": "損益を上下同じだけ倍にします。10倍なら、逆行10%で残り90%になるのではなく強制決済されます。強制決済は全損より先に来ます。",
