  "stratWinRateNote": "このページの勝率について：各スタイルを説明するときによく使われる「目安」の範囲であって、測定された結果ではありません。標本も期間も銘柄も出典もないため、これを根拠に何かのサイズを決めることはできません。仮に測定値だったとしても、それだけではほとんど何も言えません。勝率45%でも利益が損失の3倍なら儲かり、勝率70%でも損失が利益の3倍なら損をします。決めるのは期待値——勝率×平均利益 − 負率×平均損失——であって、割合そのものではありません。あなたの期待値は、この表ではなくあなたの記録から出ます。",
