  "gl110d": "同じ3文字が、まったく無関係な2つを指します。個人向けフォーラムでは「Support and Resistance」の短縮形、つまり普通のサポートとレジスタンス。これは古典的な用語ではなく（ニソンもシュワッガーもダグラスも使いません）、学術的な略号は S/R です。クオンツの世界では「Signal-to-Noise Ratio」、価格変動のうちどれだけが利用可能な方向で、どれだけがランダムノイズかを表します。こちらは定義の明確な統計概念です。",
  "gl111t": "ボラティリティ・リスクプレミアム",
  "gl111d": "オプションに織り込まれたインプライドボラティリティと、原資産が実際に実現するボラティリティとの体系的な差。オプションの売り手は、実現が implied を上回るリスクを引き受ける対価としてこれを受け取ります。忘れられた非効率ではなく保険の価格であり、だから公表されても消えません。請求書は分割されず、まとめて一度に届きます。",
